inline constexpr int kCount = static_cast<int>(sizeof(kItems) / sizeof(kItems[0]));

inline const Info* find(int id) {
  for (const Info& i : kItems)
    if (i.id == id) return &i;
  return nullptr;
}

// Weapon `weapon` loads `ammo` in one of its modes.
inline bool loads(int weapon, int ammo) {
  const Info* w = find(weapon);
  if (!w || w->kind != kWeapon) return false;
  for (const uint16_t a : w->ammo)
    if (a && a == ammo) return true;
  return false;
}

